const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountBatchControls(box,rule,values,changed){
 if(rule.customSizeValue!==undefined){const sync=()=>{for(const key of ['width','height']){const input=box.querySelector(`[data-rf="${key}"]`);if(input)input.closest('fieldset,.field').hidden=values.size!==rule.customSizeValue;}};box.addEventListener('change',sync);sync();}
 if(rule.id==='dtf-transfers'){const note=document.createElement('p');note.className='small';box.firstElementChild.prepend(note);const sync=()=>{note.textContent=values.layout===1?'Upload one print-ready gang sheet. Enter its complete width and height, up to 22 inches wide. Keep transparent space between each design.':'Upload a transparent PNG or SVG. Enter the size of each transfer and the number of copies.';};box.addEventListener('change',sync);sync();}
 if(rule.id.startsWith('ppf-')){const stage=document.createElement('section');stage.className='ppf-selection-preview';stage.innerHTML='<h3>Your protection coverage</h3><svg viewBox="0 0 240 400" role="img" aria-label="Selected PPF panels in green"><path d="M70 15Q120 0 170 15Q196 45 190 320Q186 385 160 392L80 392Q54 385 50 320Q44 45 70 15Z" fill="#e6e9ec" stroke="#5c6673" stroke-width="3"/><path data-panel="hood" d="M65 32Q120 12 175 32L174 110Q120 90 66 110Z"/><path d="M68 117Q120 99 172 117L160 158L80 158Z" fill="#a5bccd"/><rect x="80" y="168" width="80" height="110" rx="15" fill="white"/><path data-panel="mirrors" d="M42 149L70 149L70 162L42 162ZM170 149L198 149L198 162L170 162Z"/><path data-panel="bumper" d="M65 20Q120 2 175 20L175 35Q120 20 65 35Z"/><path data-panel="fenders" d="M52 40L65 40L65 147L52 147ZM175 40L188 40L188 147L175 147Z"/><path data-panel="rockers" d="M52 170L66 170L66 327L52 327ZM174 170L188 170L188 327L174 327Z"/></svg><p data-ppf-caption></p><p class="small">Illustrative panel map; final edges and exclusions are confirmed on your vehicle.</p>';box.firstElementChild.prepend(stage);const sync=()=>{const plan=values.plan;const all=rule.id==='ppf-full';for(const p of stage.querySelectorAll('[data-panel]')){const key=p.dataset.panel,on=all||key==='mirrors'||plan>=1&&['hood','bumper','fenders'].includes(key)||plan===3&&key==='rockers';p.setAttribute('fill',on?'#8bc928':'#e6e9ec');if(key==='hood'&&plan===1&&!all)p.setAttribute('opacity','.55');else p.removeAttribute('opacity');}stage.querySelector('[data-ppf-caption]').textContent=rule.fields.find(f=>f.key==='plan').options.find(o=>o.value===plan)?.label||'';};box.addEventListener('change',sync);sync();}
 if(rule.id==='tint-vehicle'){
  const keys=['glass_fl','glass_fr','glass_rl','glass_rr','glass_back','glass_strip'],shapes=['M55 88L90 100L90 151L52 145Z','M130 100L165 88L168 145L130 151Z','M52 158L90 164L90 209L54 218Z','M130 164L168 158L166 218L130 209Z','M62 232Q110 220 158 232L151 254Q110 266 69 254Z','M60 67Q110 55 160 67L153 82Q110 70 67 82Z'];
  const h=document.createElement('section');h.className='tint-glass-map';h.innerHTML=`<h3>Select your windows</h3><p>Tap each glass panel to add or remove it from the estimate.</p><svg viewBox="0 0 220 300" aria-label="Vehicle glass selection"><path d="M64 20Q110 6 156 20Q181 48 179 145L179 246Q176 284 152 289L68 289Q44 284 41 246L41 145Q39 48 64 20Z" fill="#f0f2f4" stroke="#64748b" stroke-width="3"/><path d="M93 89L127 89L127 223L93 223Z" fill="white" stroke="#ccd2dc"/>${keys.map((k,i)=>`<g role="button" tabindex="0" aria-label="${esc(rule.fields.find(f=>f.key===k).label)}" data-glass="${k}"><path d="${shapes[i]}"/><title>${esc(rule.fields.find(f=>f.key===k).label)}</title></g>`).join('')}</svg><p data-glass-status role="status"></p>`;box.firstElementChild.prepend(h);
  const sync=()=>{for(const k of keys){const g=h.querySelector(`[data-glass="${k}"]`);g.setAttribute('aria-pressed',!!values[k]);g.querySelector('path').setAttribute('fill',values[k]?'#c91c50':'#d6e5ee');const input=box.querySelector(`[data-rf="${k}"]`);if(input)input.checked=!!values[k];}h.querySelector('[data-glass-status]').textContent=keys.filter(k=>values[k]).length+' panels selected';};const toggle=e=>{const g=e.target.closest('[data-glass]');if(!g)return;values[g.dataset.glass]=1-values[g.dataset.glass];sync();changed();};h.onclick=toggle;h.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle(e);}};box.addEventListener('change',sync);sync();
 }
 if(rule.id.startsWith('tint-')){
  const f=rule.fields.find(f=>f.key==='vlt'),input=box.querySelector('[data-rf="vlt"]'),group=input?.closest('fieldset');if(!f||!group)return;
  const preview=document.createElement('section');preview.className='tint-light-preview';preview.innerHTML='<h3>Light transmission</h3><div class="tint-preview-scene"><img src="/satin/img/tint-1.jpg" alt="View through tinted glass"><div data-tint-shade></div></div><p data-tint-value></p><p class="small">Visual illustration; screen colours do not represent a measured VLT.</p><p class="tint-legal" data-tint-legal></p>';
  group.after(preview);if(rule.id==='tint-vehicle'){group.innerHTML=`<legend>${esc(f.label)}</legend><input aria-label="Tint shade" type="range" min="0" max="${f.options.length-1}" step="1" value="${f.options.findIndex(o=>o.value===values.vlt)}" data-vlt-slider><div class="vlt-stops">${f.options.map(o=>'<span>'+o.label+'</span>').join('')}</div>`;group.querySelector('input').oninput=e=>{values.vlt=f.options[Number(e.target.value)].value;sync();changed();};}
  function sync(){preview.querySelector('[data-tint-shade]').style.background=`rgba(0,0,0,${1-values.vlt/100})`;preview.querySelector('[data-tint-value]').textContent=values.vlt+'% visible light transmission';const legal=preview.querySelector('[data-tint-legal]');legal.textContent=rule.id==='tint-vehicle'&&values.vlt<70&&(values.glass_fl||values.glass_fr)?'Ontario: front side windows on vehicles manufactured from January 1, 2017 require at least 70% VLT for inspection. This selection is below that level. We will confirm legal placement before installation; an appointment request is not a confirmed booking.':'';}
  box.addEventListener('change',sync);sync();
 }
 if(rule.id.startsWith('design-')&&rule.id!=='design-services'){const sync=()=>{const b=box.querySelector('[data-rule-add]'),q=box.querySelector('[data-quote]');b.hidden=values.purchase===0;q.textContent=values.purchase===0?'Quote price':'Get exact quote';q.dataset.quote='Vehicle Wraps';};box.addEventListener('change',sync);sync();}
 if(rule.id==='wrap-prints'){const p=document.createElement('p');p.className='small';p.textContent=rule.priceNote;box.firstElementChild.prepend(p);const height=box.querySelector('[data-rf="height"]');box.addEventListener('change',()=>{height.max=values.kind===1?48:52;});}
}
